1	package com.acme.tmpl;
2	
3	import java.io.IOException;
4	import java.nio.charset.StandardCharsets;
5	import java.nio.file.Files;
6	import java.nio.file.Path;
7	import java.nio.file.Paths;
8	
9	import org.apache.commons.lang3.StringUtils;
10	import org.apache.commons.text.StringSubstitutor;
11	
12	/**
13	 * tmpl-svc — the tenant-config template renderer for the analytics platform.
14	 *
15	 * It reads a tenant configuration template (external, tenant-supplied text) and
16	 * resolves its ${...} placeholders with the library's default interpolator, then
17	 * writes the rendered configuration out. Because tenant-supplied text flows
18	 * straight into the default interpolator, the commons-text implementation on the
19	 * delivery classpath is what governs how those placeholders are resolved.
20	 */
21	public final class TemplateConvertApp {
22	
23	    private TemplateConvertApp() {
24	    }
25	
26	    /** Read the tenant-supplied config template, or fall back to a default. */
27	    private static String readTemplate() {
28	        Path tpl = Paths.get("data", "tenant-config.txt");
29	        try {
30	            if (Files.exists(tpl)) {
31	                String text = new String(Files.readAllBytes(tpl), StandardCharsets.UTF_8);
32	                if (StringUtils.isNotBlank(text)) {
33	                    return text;
34	                }
35	            }
36	        } catch (IOException e) {
37	            // fall through to the default template
38	        }
39	        return "service.banner=Welcome ${sys:tenant.name}";
40	    }
41	
42	    public static void main(String[] args) throws IOException {
43	        String template = readTemplate();
44	        // Tenant-supplied template flows into the default interpolator.
45	        StringSubstitutor interpolator = StringSubstitutor.createInterpolator();
46	        String rendered = interpolator.replace(template);
47	
48	        Path out = Paths.get("out");
49	        Files.createDirectories(out);
50	        Files.write(out.resolve("conversion.log"),
51	                ("Converted config:\n" + rendered + "\n").getBytes(StandardCharsets.UTF_8));
52	
53	        System.out.println("tmpl-svc: rendered tenant configuration ->");
54	        for (String line : rendered.split("\n", -1)) {
55	            if (!line.isEmpty()) {
56	                System.out.println("  " + line);
57	            }
58	        }
59	    }
60	}
